def parse_str(input_str):
    """
    Parse a string and return an object with the attributes type, intensity, size, generation, and choice.

    Args:
        input_str (str): A string of the format "type=<type>;intensity=<intensity>;size=<size>;generation=<gen>;choice=<choice>"

    Returns:
        object: An object with the attributes type, intensity, size, generation, and choice

    Raises:
        ValueError: If the input string is invalid
    """

    def parse_attr(key, value):
        try:
            return eval(value)
        except NameError:
            raise ValueError(f"Invalid value for '{key}': '{value}'")
        except Exception as e:
            raise ValueError(f"Error parsing '{key}': {str(e)}")

    parts = input_str.split(';')
    if len(parts)!= 5:
        raise ValueError("Invalid input string. Expected 5 parts separated by ';'")

    attr_dict = {}
    for part in parts:
        key, value = part.split('=')
        key = key.strip().lower()
        value = value.strip()
        if key not in ['type', 'intensity','size', 'generation', 'choice']:
            raise ValueError(f"Invalid attribute '{key}'")
        attr_dict[key] = parse_attr(key, value)

    return type('Result', (), attr_dict)
