def parse_string(input_string):
    """
    Parse a string and return an object with type, intensity, size, generation, and choice attributes.

    Args:
        input_string (str): A string containing values in the format '{"type": <type>, "intensity": <int>, "size": <int>, "generation": <int>, "choice": <int>}'

    Returns:
        object: An object with type, intensity, size, generation, and choice attributes.

    Raises:
        ValueError: If the input string is invalid.
    """
    try:
        data = eval(input_string.replace('\\', '\\\\').replace('"', '\\"'))
        if not isinstance(data, dict):
            raise ValueError("Invalid input string")
        if not all(key in data for key in ["type", "intensity", "size", "generation", "choice"]):
            raise ValueError("Invalid input string")

        if not isinstance(data["type"], str) or not data["type"].lower() in ["fire", "water", "grass", "electric", "ice", "fighting", "poison", "ground", "flying", "bug", "psychic", "fairy", "rock", "ghost", "dragon", "dark", "steel", "fairy", "normal"]:
            raise ValueError("Invalid type")

        if not (isinstance(data["intensity"], int) and data["intensity"] >= 0):
            raise ValueError("Invalid intensity")

        if not (isinstance(data["size"], int) and data["size"] > 0):
            raise ValueError("Invalid size")

        if not (isinstance(data["generation"], int) and data["generation"] >= 1 and data["generation"] <= 8):
            raise ValueError("Invalid generation")

        if not (isinstance(data["choice"], int) and data["choice"] > 0):
            raise ValueError("Invalid choice")

        return object()
    except SyntaxError:
        raise ValueError("Invalid input string")
