def validate_code(code, reference_implementations):
    with tempfile.NamedTemporaryFile(mode='w', suffix='.py', delete=False) as f:
        f.write(code)
        filename = f.name

    try:
        tree = ast.parse(code)
        ast.check_type(tree)
    except SyntaxError as e:
        print(f"Invalid syntax: {e}")
        return False

