            with io.StringIO() as std_err:
                with tempfile.tempdir():
                    sys.stdout = std_out
                    sys.stderr = std_err
                    exec(compile(open(filename, 'rb').read(), filename, 'exec'))
                    sys.stdout.seek(0)
                    output = std_out.read()
                    sys.stdout = sys.__stdout__
