import os
import shutil
import argparse

def rename_files(file_paths, dest_dir, rename_rules):
    files = {}
    for file_path in file_paths:
        filename = os.path.basename(file_path)
        filename_no_ext = os.path.splitext(filename)[0]
        files[filename] = {
            'path': file_path,
            'extension': os.path.splitext(filename)[1],
            'ext_original': filename
        }

    for filename, attrs in files.items():
        new_filename = rename_rules.generate(attrs)

        new_path = os.path.join(dest_dir, new_filename)
        new_full_path = os.path.join(dest_dir, os.path.basename(new_path))
        shutil.copy(attrs['path'], new_path)
        os.replace(new_full_path, attrs['path'].replace(attrs['ext_original'], attrs['extension']))

class RenameRules:
    def __init__(self):
        self.rules = {}

    def add_rule(self, pattern, replace_with):
        self.rules[pattern] = replace_with

    def generate(self, attrs):
        filename = attrs['ext_original']
        for pattern, replace_with in self.rules.items():
            filename = os.path.splitext(filename)[0].replace(pattern, replace_with) + attrs['extension']
        return filename

def main():
    parser = argparse.ArgumentParser(description='Rename files according to rules')
    parser.add_argument('file_paths', type=str, nargs='+', help='Paths to the files to rename')
    parser.add_argument('dest_dir', type=str, help='Destination directory')
    parser.add_argument('--rules', type=str, nargs='+', help='Rules for renaming (in format "pattern old" "pattern new")')

    args = parser.parse_args()

    rules = RenameRules()
    for rule in args.rules:
        pattern, replace_with = rule.split()
        rules.add_rule(pattern, replace_with)

    copy_files = [path for path in args.file_paths]
    rename_files(copy_files, args.dest_dir, rules)

if __name__ == "__main__":
    import sys
    sys.argv[0] = 'tool'
    args = sys.argv[1:]

    if "--help" in sys.argv[1:]:
        print("Usage: tool.py <paths> <dest_dir> (--rules rule1 [rule2...])")
        exit()

    import sys
    sys.argv[1:] = [arg for arg in args if not arg.startswith("--")]

    main()
