from typing import Callable, Dict

def apply_primitive(env: Dict[str, Callable[[...],...]]) -> Callable[[str],...]:
    def apply_primitive_inner(expr: str) ->...:
        parts = expr.lstrip().split()
        if len(parts) == 0:
            raise Exception('empty expression')

        if parts[0] in env:
            # variable reference
            if len(parts)!= 1:
                raise Exception('too many parts')
            return env[parts[0]]()
        elif parts[0] == 'define':
            # variable definition
            if len(parts)!= 3:
                raise Exception('invalid definition')
            var, value_expr = parts[1], expr[len('define'+ var +''):].lstrip()
            env[var] = eval_in_env(env, value_expr)
            return env[var]()
        else:
            # constant literal
            raise Exception('unknown primitive')

    return apply_primitive_inner

def eval_in_env(env: Dict[str, Callable[[...],...]], expr: str) ->...:
    parts = expr.lstrip().split()
    if len(parts) == 0:
        raise Exception('empty expression')

    if parts[0] in env:
        # variable reference
        if len(parts)!= 1:
            raise Exception('too many parts')
        return env[parts[0]]()

    if parts[0] == 'define':
        # variable definition
        if len(parts)!= 3:
            raise Exception('invalid definition')
        var, value_expr = parts[1], expr[len('define'+ var +''):].lstrip()
        env[var] = eval_in_env(env, value_expr)
        return env[var]()

    for i, part in enumerate(parts):
        if not part.isidentifier() and not part.lstrip('-').replace('.', '', 1).isidentifier():
            value_expr = expr[expr.find(part):expr.find(' ', 1 + expr.find(part))]
            break
    else:
        # constant literal
        try:
            return eval(expr)
        except Exception as e:
            return e

    # subexpression
    value_expr = expr[:parts.index(part)] + expr[1 + expr.find(part):]
    return eval_in_env(env, value_expr)

def eval_expr(expr: str, env: Dict[str, Callable[[...],...]]) ->...:
