        indents = [0] * len(func_lines)

        for i in range(len(func_lines)):
            strip_str = func_lines[i].lstrip()
            indents[i] = len(func_lines[i]) - len(strip_str)

        func_name = func_lines[0].split()[1]

        # Initialize the function code and current indent level
        curr_indent = 0
        func_code = []
        inner_funcs = {}

        # Parse the function code
