            if len(line) == indents[0]:
                # End of function
                break
            if indents[0] < curr_indent:
                # End of an inner function
                func_code_str = '\n'.join(func_code)
                inner_func_name = f'func_{len(inner_funcs)}'
                exec(compile(func_code_str, '<exec>', 'exec'), namespace, inner_funcs)
                namespace[inner_func_name] = inner_funcs[inner_func_name]
                curr_indent -= indents.pop(0)
