def eval_test_cases(test_cases):
    """
    Evaluates a list of test cases, executing each test function with the provided test case arguments.

    Args:
        test_cases: A list of tuples, where each tuple contains the name of a test function and a string describing the expected output.

    Returns:
        None
    """
    total_tests = len(test_cases)
    failed_tests = 0

    for i, (test_func_name, expected_output) in enumerate(test_cases):
        try:
            # Store the eval function as an attribute of the current dictionary's parent to prevent eval to be used as evil
            self = {'eval': eval}
            try:
                output = self['eval'](test_func_name + '(' + str([arg for arg in test_cases[i + 1].split(':')[1] if arg.strip()] or ["()"]) + ')')
                test_cases.pop(0)  # Shift the first test case after it has been evaluated to prevent indexing errors
            except SyntaxError:
                print(f"Error: Test function '{test_func_name}' is not a valid Python expression.")
                continue

            if str(output)!= expected_output:
                print(f"Test {i + 1} failed: Output '{str(output)}' did not match expected output '{expected_output}'")
                failed_tests += 1
            else:
                print(f"Test {i + 1} passed: Expected output '{expected_output}' matches actual output '{str(output)}'")
        except Exception as e:
            print(f"Test {i + 1} failed with exception: {str(e)}")
            failed_tests += 1

