import ast

def evaluate_lock_definition(lock_definition):
    try:
        tree = ast.parse(lock_definition)
    except SyntaxError as e:
        raise ValueError(f"Invalid lock definition: {str(e)}")

    warnings = []
    evaluated_definitions = []

    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            func_name = node.name
            args = [arg.arg for arg in node.args.args]
            keywords = {k.arg: k.value for k in node.args.keywords}

            func = eval(f"lambda {', '.join(args)}: {node.body.args[0].value}", {}, {})
